package app.entities

import org.jetbrains.exposed.v1.core.ReferenceOption
import org.jetbrains.exposed.v1.core.Table

/**
 * The "product_tags" table, as the database has it. Exposed never creates or changes it: the database already exists.
 */
object ProductTagTable : Table("product_tags") {
    val productId = long("product_id")
    val tagId = long("tag_id")

    override val primaryKey = PrimaryKey(productId, tagId)

    init {
        foreignKey(productId to ProductTable.id, onDelete = ReferenceOption.CASCADE)
        foreignKey(tagId to TagTable.id, onDelete = ReferenceOption.CASCADE)
    }
}

