package app.services

import app.UnitOfWork
import app.common.Page
import app.entities.Category
import app.errors.ConflictException
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException

/** Operations on categories. Each write runs in its own transaction. */
class CategoryService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Category after checking it. */
    fun createCategory(category: Category): Category {
        val values = mapOf(
            "name" to category.name,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            uow.categories.insert(category)
        }
    }

    /** The Category with this key; NotFoundException when there is none. */
    fun getCategory(id: Long): Category = find(unitOfWork, id)

    /** A page of categories, by primary key. */
    fun listCategories(offset: Int, limit: Int): Page<Category> = unitOfWork.categories.list(offset, limit)

    /** Changes the given values of a Category. */
    fun updateCategory(id: Long, changes: CategoryChanges): Category {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.categories.update(current)
        }
    }

    /** Deletes a Category. */
    fun deleteCategory(id: Long) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (uow.products.listByCategoryId(current.id!!).isNotEmpty())
                throw ConflictException("Category", "rows of products still point to it", listOf("products"))
            uow.categories.delete(current)
        }
    }

    /** The Category with this name, or null. */
    fun findCategoryByName(name: String): Category? = unitOfWork.categories.findByName(name)

    /** Checks the values against the rules of the "categories" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Category?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["name"]
            if (value == null) {
                if (creating || "name" in values) errors += FieldError("name", "is required")
            } else {
                if (value is String && value.length > 60) errors += FieldError("name", "is longer than 60 characters")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Category", errors)
    }

    /** Values that must be unique are not taken by another row. */
    private fun checkUnique(uow: UnitOfWork, values: Map<String, Any?>, current: Category?) {
        run {
            val name = if ("name" in values) values["name"] as String? else current?.name
            if (name != null) {
                val other = uow.categories.findByName(name)
                if (other != null && (current == null || other.id != current.id))
                    throw ConflictException("Category", "name is already taken", listOf("name"))
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Category?) {
        validate(uow, values, current)
        checkUnique(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Category, values: Map<String, Any?>) {
        if ("name" in values) entity.name = values["name"] as String?
    }

    /** The Category with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: Long): Category =
        uow.categories.findById(id) ?: throw NotFoundException("Category", id)

    /** The values an update gives, by field. */
    private fun given(changes: CategoryChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.name.isPresent) values["name"] = changes.name.value
        return values
    }
}

