import app.errors.ValidationFailedException

/** Operations on customers. Each write runs in its own transaction. */
class CustomerService(private val unitOfWork: UnitOfWork) {
    // TODO: password_hash is returned with the entity; use DTOs to leave it out

    /** Stores a new Customer after checking it. */
    fun createCustomer(customer: Customer): Customer {
        val values = mapOf(
            "email" to customer.email,
            "passwordHash" to customer.passwordHash,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            uow.customers.insert(customer)
        }
    }

    /** The Customer with this key; NotFoundException when there is none. */
    fun getCustomer(id: Long): Customer = find(unitOfWork, id)

    /** A page of customers, by primary key. */
    fun listCustomers(offset: Int, limit: Int): Page<Customer> = unitOfWork.customers.list(offset, limit)

    /** Changes the given values of a Customer. */
    fun updateCustomer(id: Long, changes: CustomerChanges): Customer {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.customers.update(current)
        }
    }

    /** Deletes a Customer. */
    fun deleteCustomer(id: Long) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (uow.orders.listByCustomerId(current.id!!).isNotEmpty())
                throw ConflictException("Customer", "rows of orders still point to it", listOf("orders"))
            uow.customers.delete(current)
        }
    }

    /** The Customer with this email, or null. */
    fun findCustomerByEmail(email: String): Customer? = unitOfWork.customers.findByEmail(email)

    /** Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Customer?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["email"]
            if (value == null) {
                if (creating || "email" in values) errors += FieldError("email", "is required")
            } else {
                if (value is String && value.length > 120) errors += FieldError("email", "is longer than 120 characters")
            }
        }
        run {
            val value = values["passwordHash"]
            if (value == null) {
                if (creating || "passwordHash" in values) errors += FieldError("password_hash", "is required")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Customer", errors)
    }

    /** Values that must be unique are not taken by another row. */
    private fun checkUnique(uow: UnitOfWork, values: Map<String, Any?>, current: Customer?) {
        run {
            val email = if ("email" in values) values["email"] as String? else current?.email
            if (email != null) {
                val other = uow.customers.findByEmail(email)
                if (other != null && (current == null || other.id != current.id))
                    throw ConflictException("Customer", "email is already taken", listOf("email"))
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Customer?) {
        validate(uow, values, current)
        checkUnique(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Customer, values: Map<String, Any?>) {
        if ("email" in values) entity.email = values["email"] as String?
        if ("passwordHash" in values) entity.passwordHash = values["passwordHash"] as String?
    }

    /** The Customer with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: Long): Customer =
        uow.customers.findById(id) ?: throw NotFoundException("Customer", id)

    /** The values an update gives, by field. */
    private fun given(changes: CustomerChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.email.isPresent) values["email"] = changes.email.value
        if (changes.passwordHash.isPresent) values["passwordHash"] = changes.passwordHash.value
        return values
    }
}

