    fun refusesAMissingValue() {
        val service = TagService(uow)
        val row = Factories.newTag(1)
        row.label = null
        val error = assertFailsWith<ValidationFailedException> { service.createTag(row) }
        assertEquals(listOf("label"), error.errors.map { it.field })
    }

    @Test
    fun saysWhenARowIsMissing() {
        val service = TagService(uow)
        assertFailsWith<NotFoundException> { service.getTag(999999L) }
    }

    @Test
    fun changesARow() {
        val service = TagService(uow)
        val row = Factories.newTag(1)
        val created = service.createTag(row)
        val updated = service.updateTag(created.id!!, TagChanges(label = Patch.of("changed")))
        assertEquals("changed", updated.label)
    }

    @Test
    fun deletesARow() {
        val service = TagService(uow)
        val row = Factories.newTag(1)
        val created = service.createTag(row)
        service.deleteTag(created.id!!)
        assertFailsWith<NotFoundException> { service.getTag(created.id!!) }
    }
}

